   230	        Preconditions.checkArgument(right instanceof Comparable, "%s is not comparable", right);
   231	        @SuppressWarnings("unchecked")
   232	        final Comparable<Object> rightComparable = (Comparable<Object>) right;
   233	
   234	        final int compare = leftComparable.compareTo(rightComparable);
