   110	              : Filters.and(Filters.exists(field), Filters.ne(field, null), Filters.ne(field, Collections.emptyList()));
   111	    }
   112	
   113	    if (op == IterableOperators.ALL || op == IterableOperators.NONE ||
   114	            op == IterableOperators.ANY && requiresScopedAny(args.get(1))) {
   115	      return new ScopedMongoExpression(this.naming, this.codecRegistry).filter(call);
   116	    }
   117	    
   118	    if (op == IterableOperators.ANY) {
   119	      Call rightCall = call;
   120	      Path path = null;
   121	
   122	      while (rightCall.operator() == IterableOperators.ANY) {
   123	        Preconditions.checkArgument(rightCall.arguments().size() == 2, "Expected two arguments for %s got %s", rightCall, rightCall.arguments().size());
   124	        Preconditions.checkArgument(rightCall.arguments().get(0) instanceof Path, "%s is not a path", rightCall.arguments().get(0));
   125	        Preconditions.checkArgument(rightCall.arguments().get(1) instanceof Call, "%s is not a call", rightCall.arguments().get(1));
   126	
   127	        Path subPath = (Path) rightCall.arguments().get(0);
   128	        if (path != null) {
   129	          for (java.lang.reflect.Member member : subPath.members()) {
   130	            path = path.append(member);
   131	          }
   132	        } else {
   133	          path = subPath;
   134	        }
   135	        rightCall = (Call) rightCall.arguments().get(1);
   136	      }
   137	
   138	      // Handle AND/OR/NOT operators within ANY (for compound conditions on array elements).
   139	      // Also use $elemMatch for NOT_EQUAL and NOT_IN: flat dot-path $ne/$nin means "no element
   140	      // matches" (universal), but any().isNot/notIn requires existential ("at least one element").
   655	    }
   656	
   657	    @Override
   658	    public BsonValue visit(Constant constant) {
   659	      Object value = constant.value();
   660	      if (value == null) {
   661	        return BsonNull.VALUE;
   662	      }
   663	
   664	      if (value instanceof Iterable) {
   665	        return Filters.in("ignore", (Iterable<?>) value)
   666	                .toBsonDocument(BsonDocument.class, this.codecRegistry)
   667	                .get("ignore").asDocument()
   668	                .get("$in").asArray();
   669	      }
   670	
   671	      return Filters.eq("ignore", value)
   672	              .toBsonDocument(BsonDocument.class, this.codecRegistry)
   673	              .get("ignore");
   674	    }
   675	  }
   676	
   677	  private static class ScopedMongoExpression {
   678	    private final PathNaming pathNaming;
   679	    private final CodecRegistry codecRegistry;
   680	    private int variableCounter;
   681	
   682	    private ScopedMongoExpression(PathNaming pathNaming, CodecRegistry codecRegistry) {
   683	      this.pathNaming = pathNaming;
   684	      this.codecRegistry = codecRegistry;
   685	    }
   686	
   687	    private Bson filter(Call call) {
   688	      return new BsonDocument("$expr", eq(predicate(call, null), BsonBoolean.TRUE));
   689	    }
   690	
   691	    private BsonValue predicate(Expression expression, String variable) {
   692	      Preconditions.checkArgument(expression instanceof Call, "%s is not a call", expression);
   693	      Call call = (Call) expression;
   694	      Operator operator = call.operator();
   695	
   696	      if (operator == Operators.AND || operator == Operators.OR) {
   697	        List<BsonValue> values = call.arguments().stream()
   698	                .map(argument -> predicate(argument, variable))
   699	                .collect(Collectors.toList());
   700	        return logical(operator, values);
   701	      }
   702	
   703	      if (operator == Operators.NOT) {
   704	        return triNot(predicate(call.arguments().get(0), variable));
   705	      }
   706	
   707	      if (operator == IterableOperators.ANY || operator == IterableOperators.ALL || operator == IterableOperators.NONE) {
   708	        Value input = value(call.arguments().get(0), variable);
   709	        String elementVariable = "criteria" + variableCounter++;
   710	        BsonValue elementPredicate = predicate(call.arguments().get(1), elementVariable);
   711	        BsonDocument map = new BsonDocument("$map", new BsonDocument("input", input.expression)
   712	                .append("as", new BsonString(elementVariable))
   713	                .append("in", eq(elementPredicate, BsonBoolean.TRUE)));
   714	        BsonValue quantified;
   715	        if (operator == IterableOperators.ALL) {
   716	          quantified = new BsonDocument("$allElementsTrue", array(map));
   717	        } else {
   718	          BsonValue any = new BsonDocument("$anyElementTrue", array(map));
   719	          quantified = operator == IterableOperators.ANY ? any : not(any);
   720	        }
   721	        return guarded(isArray(input.expression), quantified);
   722	      }
   723	
   724	      if (operator == OptionalOperators.IS_ABSENT || operator == OptionalOperators.IS_PRESENT) {
   725	        Value input = value(call.arguments().get(0), variable);
   726	        BsonValue absent = not(known(input.expression));
   727	        return operator == OptionalOperators.IS_ABSENT ? absent : not(absent);
   728	      }
   729	
   730	      if (operator == IterableOperators.IS_EMPTY || operator == IterableOperators.NOT_EMPTY) {
   731	        Value input = value(call.arguments().get(0), variable);
   732	        BsonValue empty = eq(new BsonDocument("$size", input.expression), new org.bson.BsonInt32(0));
   733	        return guarded(isArray(input.expression), operator == IterableOperators.IS_EMPTY ? empty : not(empty));
   734	      }
