    19	    this.generator = TypeHolder.StringHolder.generator();
    20	  }
    21	
    22	  private void populate() {
    23	    repository.insert(generator.get().withId("empty").withArray().withList());
    24	    repository.insert(generator.get().withId("all-a").withArray("a", "aa").withList("a", "aa"));
    25	    repository.insert(generator.get().withId("mixed").withArray("a", "b").withList("a", "b"));
    26	    repository.insert(generator.get().withId("no-a").withArray("b", "c").withList("b", "c"));
    27	    repository.insert(generator.get().withId("null-element").withArray("a", null).withList("a"));
    28	    repository.insert(generator.get().withId("line-break").withArray("a\n").withList("a\n"));
    29	  }
