    31	  @Test
    32	  void scalarQuantifiers() {
    33	    populate();
    34	    ids(string.array.any().startsWith("a")).hasContentInAnyOrder("all-a", "mixed", "null-element", "line-break");
    35	    ids(string.array.all().startsWith("a")).hasContentInAnyOrder("empty", "all-a", "line-break");
    36	    ids(string.array.none().startsWith("a")).hasContentInAnyOrder("empty", "no-a");
    37	
    38	    ids(string.list.any().is("a")).hasContentInAnyOrder("all-a", "mixed", "null-element");
    39	    ids(string.list.all().isNot("b")).hasContentInAnyOrder("empty", "all-a", "null-element", "line-break");
    40	    ids(string.list.none().is("a")).hasContentInAnyOrder("empty", "no-a", "line-break");
    41	  }
    42	
    43	  @Test
    44	  void nullElementsDoNotMatchNegativePredicates() {
    45	    populate();
    46	    ids(string.array.all().isNot("b")).hasContentInAnyOrder("empty", "all-a", "line-break");
    47	    ids(string.array.none().isNot("b")).hasContentInAnyOrder("empty");
    48	  }
    49	
    50	  @Test
    51	  void stringLengthIncludesLineBreaks() {
    52	    populate();
    53	    ids(string.array.any().hasLength(2)).hasContentInAnyOrder("all-a", "line-break");
    54	    ids(string.array.all().hasLength(2)).hasContentInAnyOrder("empty", "line-break");
    55	    ids(string.array.none().hasLength(2)).hasContentInAnyOrder("empty", "mixed", "no-a", "null-element");
    56	  }
