    58	  private IterableChecker<List<String>, String> ids(StringHolderCriteria criteria) {
    59	    return CriteriaChecker.<TypeHolder.StringHolder>ofReader(repository.find(criteria)).toList(TypeHolder.StringHolder::id);
    60	  }
    61	}
